ALTER TABLE tenants ADD COLUMN IF NOT EXISTS operational_phone varchar(30), ADD COLUMN IF NOT EXISTS sms_enabled boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS sms_booking_confirmation_enabled boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS sms_booking_reschedule_enabled boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS sms_booking_cancellation_enabled boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS sms_appointment_reminders_enabled boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS sms_form_delivery_enabled boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS sms_form_reminders_enabled boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS sms_payment_confirmation_enabled boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS sms_refund_updates_enabled boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS sms_reminder_timing varchar(30) NOT NULL DEFAULT '24_hours_before';
ALTER TABLE clients ADD COLUMN IF NOT EXISTS phone_e164 varchar(20), ADD COLUMN IF NOT EXISTS sms_transactional_status varchar(20) NOT NULL DEFAULT 'UNKNOWN', ADD COLUMN IF NOT EXISTS sms_marketing_status varchar(20) NOT NULL DEFAULT 'UNKNOWN', ADD COLUMN IF NOT EXISTS sms_opted_out_at timestamptz, ADD COLUMN IF NOT EXISTS sms_opted_in_at timestamptz, ADD COLUMN IF NOT EXISTS sms_suppression_reason varchar(100), ADD COLUMN IF NOT EXISTS sms_last_confirmed_at timestamptz;
CREATE TABLE IF NOT EXISTS sms_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, client_id uuid REFERENCES clients(id) ON DELETE SET NULL, appointment_id uuid REFERENCES appointments(id) ON DELETE SET NULL, form_assignment_id uuid REFERENCES form_assignments(id) ON DELETE SET NULL, recipient_phone_e164 varchar(20) NOT NULL, template_key varchar(80) NOT NULL, template_version varchar(20) NOT NULL DEFAULT '1.0.0', template_data_json jsonb NOT NULL DEFAULT '{}', idempotency_key varchar(255) NOT NULL UNIQUE, status varchar(30) NOT NULL DEFAULT 'PENDING', provider varchar(30) NOT NULL DEFAULT 'twilio', provider_message_sid varchar(64) UNIQUE, scheduled_for timestamptz NOT NULL DEFAULT now(), valid_until timestamptz, attempt_count integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), segment_count integer, encoding varchar(10), last_error_code varchar(100), created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz, delivered_at timestamptz, failed_at timestamptz);
CREATE INDEX IF NOT EXISTS sms_outbox_claim_idx ON sms_outbox(status,next_attempt_at,scheduled_for);
CREATE INDEX IF NOT EXISTS sms_outbox_tenant_created_idx ON sms_outbox(tenant_id,created_at DESC);
ALTER TABLE sms_outbox ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON sms_outbox FROM anon, authenticated;
GRANT ALL ON sms_outbox TO service_role;
CREATE TABLE IF NOT EXISTS twilio_webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_key varchar(255) NOT NULL UNIQUE, event_type varchar(30) NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE twilio_webhook_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON twilio_webhook_events FROM anon, authenticated;
GRANT ALL ON twilio_webhook_events TO service_role;
